window.RP_SESSION={"id":"S-3114c34b56f3","messages":[{"id":"RP-II-0145682","time":"2026-08-11T14:22:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"쓱-\n\n 싹-\n\n쓱-\n\n 싹-...\n\n 숀과의 훈련을 마치고, 길드로 들어온 조바.. \n\n 그는 지금 갑자기 길드 복도가 좀 더러워 보인다는 생각에 스스로 빗자루를 들고 복도를 청소하고 있습니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0145683","time":"2026-08-11T14:31:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" ♪♬~ \"\n\n 빗자루질을 할 때마다 들리는 이 '쓱,싹-' 소리와 걸음걸음마다 들리는 구두와 바닥이 맞닿는 소리.\n\n 그 두 소리가 흥겹게 어울리니, 빗자루질이 지루하지 않습니다. \n콧노래가 절로 나오네요!","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0145684","time":"2026-08-11T14:47:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 내가 상상하고~ 꿈꾸던 사람~ 그대~ ♬ \"\n\n 이젠 아예, 노래도 흥얼거리고, 춤추는 듯이 몸을 이리저리 흔드네요.\n\n 누가 보면 좀 쪽팔릴 수도 있겠습니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0145685","time":"2026-08-11T15:11:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n\" 아차, 나 청소 중이었지.. \"\n\n 다시 정신을 차리곤, 빗자루를 들고 아직 청소가 덜 된 복도를 마저 청소하는 데에 집중합니다.\n\n..\n\n 청소하다가 흥에 취한 그의 뒤에서 마법으로 이루어진 실들이 나타났다가 사라진 건.. 그는 모르겠죠.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0145686","time":"2026-08-11T15:11:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0145687","time":"2026-08-11T15:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
